INSERT INTO verses (translation_id, book_id, chapter, verse, text, words_of_jesus) VALUES
('darby','GEN',1,1,'In the beginning God created the heavens and the earth.',NULL),
('darby','GEN',1,2,'And the earth was waste and empty, and darkness was on the face of the deep, and the Spirit of God was hovering over the face of the waters.',NULL),
('darby','GEN',1,3,'And God said, Let there be light. And there was light.',NULL),
('darby','GEN',1,4,'And God saw the light that it was good; and God divided between the light and the darkness.',NULL),
('darby','GEN',1,5,'And God called the light Day, and the darkness he called Night. And there was evening, and there was morning — the first day.',NULL),
('darby','GEN',1,6,'And God said, Let there be an expanse in the midst of the waters, and let it be a division between waters and waters.',NULL),
('darby','GEN',1,7,'And God made the expanse, and divided between the waters that are under the expanse and the waters that are above the expanse; and it was so.',NULL),
('darby','GEN',1,8,'And God called the expanse Heavens. And there was evening, and there was morning — a second day.',NULL),
('darby','GEN',1,9,'And God said, Let the waters under the heavens be gathered together to one place, and let the dry [land] appear. And it was so.',NULL),
('darby','GEN',1,10,'And God called the dry [land] Earth, and the gathering together of the waters he called Seas. And God saw that it was good.',NULL),
('darby','GEN',1,11,'And God said, Let the earth cause grass to spring up, herb producing seed, fruit-trees yielding fruit after their kind, the seed of which is in them, on the earth. And it was so.',NULL),
('darby','GEN',1,12,'And the earth brought forth grass, herb producing seed after its kind, and trees yielding fruit, the seed of which is in them, after their kind. And God saw that it was good.',NULL),
('darby','GEN',1,13,'And there was evening, and there was morning — a third day.',NULL),
('darby','GEN',1,14,'And God said, Let there be lights in the expanse of the heavens, to divide between the day and the night; and let them be for signs, and for seasons, and for days and years;',NULL),
('darby','GEN',1,15,'and let them be for lights in the expanse of the heavens, to give light on the earth. And it was so.',NULL),
('darby','GEN',1,16,'And God made the two great lights, the great light to rule the day, and the small light to rule the night, — and the stars.',NULL),
('darby','GEN',1,17,'And God set them in the expanse of the heavens, to give light on the earth,',NULL),
('darby','GEN',1,18,'and to rule during the day and during the night, and to divide between the light and the darkness. And God saw that it was good.',NULL),
('darby','GEN',1,19,'And there was evening, and there was morning — a fourth day.',NULL),
('darby','GEN',1,20,'And God said, Let the waters swarm with swarms of living souls, and let fowl fly above the earth in the expanse of the heavens.',NULL),
('darby','GEN',1,21,'And God created the great sea monsters, and every living soul that moves with which the waters swarm, after their kind, and every winged fowl after its kind. And God saw that it was good.',NULL),
('darby','GEN',1,22,'And God blessed them, saying, Be fruitful and multiply, and fill the waters in the seas, and let fowl multiply on the earth.',NULL),
('darby','GEN',1,23,'And there was evening, and there was morning — a fifth day.',NULL),
('darby','GEN',1,24,'And God said, Let the earth bring forth living souls after their kind, cattle, and creeping thing, and beast of the earth, after their kind. And it was so.',NULL),
('darby','GEN',1,25,'And God made the beast of the earth after its kind, and the cattle after their kind, and every creeping thing of the ground after its kind. And God saw that it was good.',NULL),
('darby','GEN',1,26,'And God said, Let us make man in our image, after our likeness; and let them have dominion over the fish of the sea, and over the fowl of the heavens, and over the cattle, and over the whole earth, and over every creeping thing that creepeth on the earth.',NULL),
('darby','GEN',1,27,'And God created Man in his image, in the image of God created he him; male and female created he them.',NULL),
('darby','GEN',1,28,'And God blessed them; and God said to them, Be fruitful and multiply, and fill the earth, and subdue it; and have dominion over the fish of the sea, and over the fowl of the heavens, and over every animal that moveth on the earth.',NULL),
('darby','GEN',1,29,'And God said, Behold, I have given you every herb producing seed that is on the whole earth, and every tree in which is the fruit of a tree producing seed: it shall be food for you;',NULL),
('darby','GEN',1,30,'and to every animal of the earth, and to every fowl of the heavens, and to everything that creepeth on the earth, in which is a living soul, every green herb for food. And it was so.',NULL),
('darby','GEN',1,31,'And God saw everything that he had made, and behold it was very good. And there was evening, and there was morning — the sixth day.',NULL),
('darby','PSA',23,1,'Jehovah is my shepherd; I shall not want.',NULL),
('darby','PSA',23,2,'He maketh me to lie down in green pastures; he leadeth me beside still waters.',NULL),
('darby','PSA',23,3,'He restoreth my soul; he leadeth me in paths of righteousness for his name''s sake.',NULL),
('darby','PSA',23,4,'Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff, they comfort me.',NULL),
('darby','PSA',23,5,'Thou preparest a table before me in the presence of mine enemies; thou hast anointed my head with oil; my cup runneth over.',NULL),
('darby','PSA',23,6,'Surely, goodness and loving-kindness shall follow me all the days of my life; and I will dwell in the house of Jehovah for the length of the days.',NULL),
('darby','PSA',117,1,'Praise Jehovah, all ye nations; laud him, all ye peoples;',NULL),
('darby','PSA',117,2,'For his loving-kindness is great toward us, and the truth of Jehovah [endureth] for ever. Hallelujah!',NULL),
('darby','MAT',11,1,'And it came to pass when Jesus had finished commanding his twelve disciples, he departed thence to teach and preach in their cities.',NULL),
('darby','MAT',11,2,'But John, having heard in the prison the works of the Christ, sent by his disciples,',NULL),
('darby','MAT',11,3,'and said to him, Art thou the coming [one]? or are we to wait for another?',NULL),
('darby','MAT',11,4,'And Jesus answering said to them, Go, report to John what ye hear and see.',NULL),
('darby','MAT',11,5,'Blind [men] see and lame walk; lepers are cleansed, and deaf hear; and dead are raised, and poor have glad tidings preached to them:',NULL),
('darby','MAT',11,6,'and blessed is whosoever shall not be offended in me.',NULL),
('darby','MAT',11,7,'But as they went [away], Jesus began to say to the crowds concerning John, What went ye out into the wilderness to see? a reed moved about by the wind?',NULL),
('darby','MAT',11,8,'But what went ye out to see? a man clothed in delicate raiment? behold, those who wear delicate things are in the houses of kings.',NULL),
('darby','MAT',11,9,'But what went ye out to see? a prophet? Yea, I say to you, and more than a prophet:',NULL),
('darby','MAT',11,10,'this is he of whom it is written, Behold, I send my messenger before thy face, who shall prepare thy way before thee.',NULL),
('darby','MAT',11,11,'Verily I say to you, that there is not arisen among [the] born of women a greater than John the baptist. But he who is a little one in the kingdom of the heavens is greater than he.',NULL),
('darby','MAT',11,12,'But from the days of John the baptist until now, the kingdom of the heavens is taken by violence, and [the] violent seize on it.',NULL),
('darby','MAT',11,13,'For all the prophets and the law have prophesied unto John.',NULL),
('darby','MAT',11,14,'And if ye will receive it, this is Elias, who is to come.',NULL),
('darby','MAT',11,15,'He that has ears to hear, let him hear.',NULL),
('darby','MAT',11,16,'But to whom shall I liken this generation? It is like children sitting in the markets, which, calling to their companions,',NULL),
('darby','MAT',11,17,'say, We have piped to you, and ye have not danced: we have mourned to you, and ye have not wailed.',NULL),
('darby','MAT',11,18,'For John has come neither eating nor drinking, and they say, He has a demon.',NULL),
('darby','MAT',11,19,'The Son of man has come eating and drinking, and they say, Behold, a man [that is] eating and wine-drinking, a friend of tax-gatherers, and of sinners: — and wisdom has been justified by her children.',NULL),
('darby','MAT',11,20,'Then began he to reproach the cities in which most of his works of power had taken place, because they had not repented.',NULL),
('darby','MAT',11,21,'Woe to thee, Chorazin! woe to thee Bethsaida! for if the works of power which have taken place in you, had taken place in Tyre and Sidon, they had long ago repented in sackcloth and ashes.',NULL),
('darby','MAT',11,22,'But I say to you, that it shall be more tolerable for Tyre and Sidon in judgment-day than for you.',NULL),
('darby','MAT',11,23,'And thou, Capernaum, who hast been raised up to heaven, shalt be brought down even to hades. For if the works of power which have taken place in thee, had taken place in Sodom, it had remained until this day.',NULL),
('darby','MAT',11,24,'But I say to you, that it shall be more tolerable for [the] land of Sodom in judgment-day than for thee.',NULL),
('darby','MAT',11,25,'At that time, Jesus answering said, I praise thee, Father, Lord of the heaven and of the earth, that thou hast hid these things from the wise and prudent, and hast revealed them to babes.',NULL),
('darby','MAT',11,26,'Yea, Father, for thus has it been well-pleasing in thy sight.',NULL),
('darby','MAT',11,27,'All things have been delivered to me by my Father, and no one knows the Son but the Father, nor does any one know the Father, but the Son, and he to whom the Son may be pleased to reveal [him].',NULL),
('darby','MAT',11,28,'Come to me, all ye who labour and are burdened, and I will give you rest.',NULL),
('darby','MAT',11,29,'Take my yoke upon you, and learn from me; for I am meek and lowly in heart; and ye shall find rest to your souls;',NULL),
('darby','MAT',11,30,'for my yoke is easy, and my burden is light.',NULL),
('darby','MAT',17,1,'And after six days Jesus takes with [him] Peter, and James, and John his brother, and brings them up into a high mountain apart.',NULL),
('darby','MAT',17,2,'And he was transfigured before them. And his face shone as the sun, and his garments became white as the light;',NULL),
('darby','MAT',17,3,'and lo, Moses and Elias appeared to them talking with him.',NULL),
('darby','MAT',17,4,'And Peter answering said to Jesus, Lord, it is good we should be here. If thou wilt, let us make here three tabernacles: for thee one, and for Moses one, and one for Elias.',NULL),
('darby','MAT',17,5,'While he was still speaking, behold, a bright cloud overshadowed them, and lo, a voice out of the cloud, saying, This is my beloved Son, in whom I have found my delight: hear him.',NULL),
('darby','MAT',17,6,'And the disciples hearing [it] fell upon their faces, and were greatly terrified.',NULL),
('darby','MAT',17,7,'And Jesus coming to [them] touched them, and said, Rise up, and be not terrified.',NULL),
('darby','MAT',17,8,'And lifting up their eyes, they saw no one but Jesus alone.',NULL),
('darby','MAT',17,9,'And as they descended from the mountain, Jesus charged them, saying, Tell the vision to no one, until the Son of man be risen up from among [the] dead.',NULL),
('darby','MAT',17,10,'And [his] disciples demanded of him saying, Why then say the scribes that Elias must first have come?',NULL),
('darby','MAT',17,11,'And he answering said to them, Elias indeed comes first and will restore all things.',NULL),
('darby','MAT',17,12,'But I say unto you that Elias has already come, and they have not known him, but have done unto him whatever they would. Thus also the Son of man is about to suffer from them.',NULL),
('darby','MAT',17,13,'Then the disciples understood that he spoke to them of John the baptist.',NULL),
('darby','MAT',17,14,'And when they came to the crowd, a man came to him, falling on his knees before him, and saying,',NULL),
('darby','MAT',17,15,'Lord, have mercy on my son, for he is lunatic, and suffers sorely; for often he falls into the fire and often into the water.',NULL),
('darby','MAT',17,16,'And I brought him to thy disciples, and they were not able to heal him.',NULL),
('darby','MAT',17,17,'And Jesus answering said, O unbelieving and perverted generation, how long shall I be with you? how long shall I bear with you? Bring him here to me.',NULL),
('darby','MAT',17,18,'And Jesus rebuked him, and the demon went out from him, and the boy was healed from that hour.',NULL),
('darby','MAT',17,19,'Then the disciples, coming to Jesus apart, said [to him], Why were not we able to cast him out?',NULL),
('darby','MAT',17,20,'And he says to them, Because of your unbelief; for verily I say unto you, If ye have faith as a grain of mustard [seed], ye shall say to this mountain, Be transported hence there, and it shall transport itself; and nothing shall be impossible to you.',NULL),
('darby','MAT',17,21,'But this kind does not go out but by prayer and fasting.',NULL),
('darby','MAT',17,22,'And while they abode in Galilee, Jesus said to them, The Son of man is about to be delivered up into [the] hands of men,',NULL),
('darby','MAT',17,23,'and they shall kill him; and the third day he shall be raised up. And they were greatly grieved.',NULL),
('darby','MAT',17,24,'And when they came to Capernaum, those who received the didrachmas came to Peter and said, Does your teacher not pay the didrachmas?',NULL),
('darby','MAT',17,25,'He says, Yes. And when he came into the house, Jesus anticipated him, saying, What dost thou think, Simon? the kings of the earth, from whom do they receive custom or tribute? from their own sons or from strangers?',NULL),
('darby','MAT',17,26,'Peter says to him, From strangers. Jesus said to him, Then are the sons free.',NULL),
('darby','MAT',17,27,'But that we may not be an offence to them, go to the sea and cast a hook, and take the first fish that comes up, and when thou hast opened its mouth thou wilt find a stater; take that and give it to them for me and thee.',NULL),
('darby','JHN',3,1,'But there was a man from among the Pharisees, his name Nicodemus, a ruler of the Jews;',NULL),
('darby','JHN',3,2,'he came to him by night, and said to him, Rabbi, we know that thou art come a teacher from God, for none can do these signs that thou doest unless God be with him.',NULL),
('darby','JHN',3,3,'Jesus answered and said to him, Verily, verily, I say unto thee, Except any one be born anew he cannot see the kingdom of God.',NULL),
('darby','JHN',3,4,'Nicodemus says to him, How can a man be born being old? can he enter a second time into the womb of his mother and be born?',NULL),
('darby','JHN',3,5,'Jesus answered, Verily, verily, I say unto thee, Except any one be born of water and of Spirit, he cannot enter into the kingdom of God.',NULL),
('darby','JHN',3,6,'That which is born of the flesh is flesh; and that which is born of the Spirit is spirit.',NULL),
('darby','JHN',3,7,'Do not wonder that I said to thee, It is needful that ye should be born anew.',NULL),
('darby','JHN',3,8,'The wind blows where it will, and thou hearest its voice, but knowest not whence it comes and where it goes: thus is every one that is born of the Spirit.',NULL),
('darby','JHN',3,9,'Nicodemus answered and said to him, How can these things be?',NULL),
('darby','JHN',3,10,'Jesus answered and said to him, Thou art the teacher of Israel and knowest not these things!',NULL),
('darby','JHN',3,11,'Verily, verily, I say unto thee, We speak that which we know, and we bear witness of that which we have seen, and ye receive not our witness.',NULL),
('darby','JHN',3,12,'If I have said the earthly things to you, and ye believe not, how, if I say the heavenly things to you, will ye believe?',NULL),
('darby','JHN',3,13,'And no one has gone up into heaven, save he who came down out of heaven, the Son of man who is in heaven.',NULL),
('darby','JHN',3,14,'And as Moses lifted up the serpent in the wilderness, thus must the Son of man be lifted up,',NULL),
('darby','JHN',3,15,'that every one who believes on him may [not perish, but] have life eternal.',NULL),
('darby','JHN',3,16,'For God so loved the world, that he gave his only-begotten Son, that whosoever believes on him may not perish, but have life eternal.',NULL),
('darby','JHN',3,17,'For God has not sent his Son into the world that he may judge the world, but that the world may be saved through him.',NULL),
('darby','JHN',3,18,'He that believes on him is not judged: but he that believes not has been already judged, because he has not believed on the name of the only-begotten Son of God.',NULL),
('darby','JHN',3,19,'And this is the judgment, that light is come into the world, and men have loved darkness rather than light; for their works were evil.',NULL),
('darby','JHN',3,20,'For every one that does evil hates the light, and does not come to the light that his works may not be shewn as they are;',NULL),
('darby','JHN',3,21,'but he that practises the truth comes to the light, that his works may be manifested that they have been wrought in God.',NULL),
('darby','JHN',3,22,'After these things came Jesus and his disciples into the land of Judaea; and there he abode with them and baptised.',NULL),
('darby','JHN',3,23,'And John also was baptising in Aenon, near Salim, because there was a great deal of water there; and they came to [him] and were baptised:',NULL),
('darby','JHN',3,24,'for John was not yet cast into prison.',NULL),
('darby','JHN',3,25,'There was therefore a reasoning of the disciples of John with a Jew about purification.',NULL),
('darby','JHN',3,26,'And they came to John and said to him, Rabbi, he who was with thee beyond the Jordan, to whom thou barest witness, behold, he baptises, and all come to him.',NULL),
('darby','JHN',3,27,'John answered and said, A man can receive nothing unless it be given him out of heaven.',NULL),
('darby','JHN',3,28,'Ye yourselves bear me witness that I said, I am not the Christ, but, that I am sent before him.',NULL),
('darby','JHN',3,29,'He that has the bride is the bridegroom; but the friend of the bridegroom, who stands and hears him, rejoices in heart because of the voice of the bridegroom: this my joy then is fulfilled.',NULL),
('darby','JHN',3,30,'He must increase, but I must decrease.',NULL),
('darby','JHN',3,31,'He who comes from above is above all. He who has his origin in the earth is of the earth, and speaks [as] of the earth. He who comes out of heaven is above all,',NULL),
('darby','JHN',3,32,'[and] what he has seen and has heard, this he testifies; and no one receives his testimony.',NULL),
('darby','JHN',3,33,'He that has received his testimony has set to his seal that God is true;',NULL),
('darby','JHN',3,34,'for he whom God has sent speaks the words of God, for God gives not the Spirit by measure.',NULL),
('darby','JHN',3,35,'The Father loves the Son, and has given all things [to be] in his hand.',NULL),
('darby','JHN',3,36,'He that believes on the Son has life eternal, and he that is not subject to the Son shall not see life, but the wrath of God abides upon him.',NULL),
('darby','3JN',1,1,'The elder to the beloved Gaius, whom I love in truth.',NULL),
('darby','3JN',1,2,'Beloved, I desire that in all things thou shouldest prosper and be in health, even as thy soul prospers.',NULL),
('darby','3JN',1,3,'For I rejoiced exceedingly when [the] brethren came and bore testimony to thy [holding fast the] truth, even as thou walkest in truth.',NULL),
('darby','3JN',1,4,'I have no greater joy than these things that I hear of my children walking in the truth.',NULL),
('darby','3JN',1,5,'Beloved, thou doest faithfully [in] whatever thou mayest have wrought towards the brethren and that strangers,',NULL),
('darby','3JN',1,6,'(who have witnessed of thy love before [the] assembly,) in setting forward whom on their journey worthily of God, thou wilt do well;',NULL),
('darby','3JN',1,7,'for for the name have they gone forth, taking nothing of those of the nations.',NULL),
('darby','3JN',1,8,'We therefore ought to receive such, that we may be fellow-workers with the truth.',NULL),
('darby','3JN',1,9,'I wrote something to the assembly; but Diotrephes, who loves to have the first place among them, receives us not.',NULL),
('darby','3JN',1,10,'For this reason, if I come, I will bring to remembrance his works which he does, babbling against us with wicked words; and not content with these, neither does he himself receive the brethren; and those who would he prevents, and casts [them] out of the assembly.',NULL),
('darby','3JN',1,11,'Beloved, do not imitate what is evil, but what is good. He that does good is of God. He that does evil has not seen God.',NULL),
('darby','3JN',1,12,'Demetrius has witness borne to him by all, and by the truth itself; and we also bear witness, and thou knowest that our witness is true.',NULL),
('darby','3JN',1,13,'I had many things to write to thee, but I will not with ink and pen write to thee;',NULL),
('darby','3JN',1,14,'but I hope soon to see thee, and we will speak mouth to mouth. Peace [be] to thee. The friends greet thee. Greet the friends by name.',NULL),
('darby','REV',12,1,'And a great sign was seen in the heaven: a woman clothed with the sun, and the moon under her feet, and upon her head a crown of twelve stars;',NULL),
('darby','REV',12,2,'and being with child she cried, [being] in travail, and in pain to bring forth.',NULL),
('darby','REV',12,3,'And another sign was seen in the heaven: and behold, a great red dragon, having seven heads and ten horns, and on his heads seven diadems;',NULL),
('darby','REV',12,4,'and his tail draws the third part of the stars of the heaven; and he cast them to the earth. And the dragon stood before the woman who was about to bring forth, in order that when she brought forth he might devour her child.',NULL),
('darby','REV',12,5,'And she brought forth a male son, who shall shepherd all the nations with an iron rod; and her child was caught up to God and to his throne.',NULL),
('darby','REV',12,6,'And the woman fled into the wilderness, where she has there a place prepared of God, that they should nourish her there a thousand two hundred [and] sixty days.',NULL),
('darby','REV',12,7,'And there was war in the heaven: Michael and his angels went to war with the dragon. And the dragon fought, and his angels;',NULL),
('darby','REV',12,8,'and he prevailed not, nor was their place found any more in the heaven.',NULL),
('darby','REV',12,9,'And the great dragon was cast out, the ancient serpent, he who is called Devil and Satan, he who deceives the whole habitable world, he was cast out into the earth, and his angels were cast out with him.',NULL),
('darby','REV',12,10,'And I heard a great voice in the heaven saying, Now is come the salvation and the power and the kingdom of our God, and the authority of his Christ; for the accuser of our brethren has been cast out, who accused them before our God day and night:',NULL),
('darby','REV',12,11,'and they have overcome him by reason of the blood of the Lamb, and by reason of the word of their testimony, and have not loved their life even unto death.',NULL),
('darby','REV',12,12,'Therefore be full of delight, ye heavens, and ye that dwell in them. Woe to the earth and to the sea, because the devil has come down to you, having great rage, knowing he has a short time.',NULL),
('darby','REV',12,13,'And when the dragon saw that he had been cast out into the earth, he persecuted the woman which bore the male [child].',NULL),
('darby','REV',12,14,'And there were given to the woman the two wings of the great eagle, that she might fly into the desert into her place, where she is nourished there a time, and times, and half a time, from [the] face of the serpent.',NULL),
('darby','REV',12,15,'And the serpent cast out of his mouth behind the woman water as a river, that he might make her be [as] one carried away by a river.',NULL),
('darby','REV',12,16,'And the earth helped the woman, and the earth opened its mouth and swallowed the river which the dragon cast out of his mouth.',NULL),
('darby','REV',12,17,'And the dragon was angry with the woman, and went to make war with the remnant of her seed, who keep the commandments of God, and have the testimony of Jesus.',NULL);
INSERT INTO chapter_titles (translation_id, book_id, chapter, text) VALUES
('darby','PSA',23,'A Psalm of David.');
INSERT INTO verses_fts (verses_fts) VALUES ('rebuild');
